src, dst = sys.argv[1], sys.argv[2]
os.makedirs(dst, exist_ok=True)
for f in sorted(glob.glob(os.path.join(src, '*.svg'))):
    s = open(f, encoding='utf-8').read()
    for en, it in sorted(IT.items(), key=lambda kv: -len(kv[0])):
        s = s.replace('>' + en + '<', '>' + it + '<').replace('aria-label="' + en + '"', 'aria-label="' + it + '"')
    s = s.replace('<svg xmlns="http://www.w3.org/2000/svg"', '<svg xmlns="http://www.w3.org/2000/svg" xml:lang="it"', 1)
    open(os.path.join(dst, os.path.basename(f)), 'w', encoding='utf-8').write(s)
